package com.wax.module.settings

/**
 * Every setting a user can override per target, with its value kind.
 *
 * Generated by tools/settings/generate_target_registry.py from the preference
 * screens. Do not hand-edit: a setting that is missing here cannot be
 * overridden, and one that is listed but no longer exists would show an empty
 * row in the interface. Regenerate instead.
 *
 * 122 settings, of which 89 are toggles.
 *
 * 21 settings are excluded on purpose: the module's own appearance and diagnostics,
 * and anything holding a credential or a file path.
 */
object SettingKeyRegistry {
    /** One setting, as the interface needs it. */
    data class Entry(
        val key: String,
        val kind: Kind,
        val category: String,
        /** The preference screen the setting is edited on. */
        val screen: String,
        /** Title string resource id, or 0 when the screen declares no title. */
        val titleRes: Int,
    ) {
        /** Whether this setting can be resolved to a plain on/off value. */
        val isToggle: Boolean get() = kind == Kind.BOOLEAN
    }

    /** The value kinds a preference can hold. */
    enum class Kind {
        BOOLEAN,
        TEXT,
        INT,
        FLOAT,
        SET,
    }

