    /** Every overrideable setting. */
    val entries: List<Entry> = ALL

    private val BY_KEY: Map<String, Entry> = ALL.associateBy { it.key }

    /** The setting for [key], or null when it cannot be overridden. */
    fun find(key: String): Entry? = BY_KEY[key]

    /** Whether [key] can carry a per-target override. */
    fun isOverrideable(key: String): Boolean = BY_KEY.containsKey(key)

    /** The settings grouped by category, categories in alphabetical order. */
    fun byCategory(): Map<String, List<Entry>> = ALL.groupBy { it.category }.toSortedMap()

    /** The toggles, which is what the interface offers as a three-way control. */
    fun toggles(): List<Entry> = ALL.filter { it.isToggle }
}
